const here=dirname(fileURLToPath(import.meta.url));
const tc=await loadToolchain();const selected=await loadComponentizer(tc);
const {splicer:stock}=await import(pathToFileURL(join(tc.directory,'node_modules/@bytecodealliance/componentize-js/lib/spidermonkey-embedding-splicer.js')));
const {componentWit,transpile}=await import(pathToFileURL(tc.require.resolve('@bytecodealliance/jco')));
const tools=resolve(process.env.NODE_COMPAT_WASM_TOOLS??'/tmp/starling-node-compat/native-build/cache/wasm-tools/1448/wasm-tools');
const engine=resolve(process.env.NODE_COMPAT_ENGINE);const engineBytes=await readFile(engine);
const output=resolve(process.env.NODE_COMPAT_RAW_ABI_OUTPUT??'/tmp/starling-node-compat/raw-i32-reader');await mkdir(output,{recursive:true});await writeFile(join(output,'package.json'),'{"type":"module"}\n');
