const watPath=join(output,'wrapper.wat'),skeletonPath=join(output,'wrapper.wasm');await writeFile(watPath,wat);const parsed=spawnSync(tools,['parse',watPath,'-o',skeletonPath],{encoding:'utf8'});assert.equal(parsed.status,0,parsed.stderr);const skeleton=await readFile(skeletonPath);const first=sections(skeleton).find(s=>s.id===1);assert(first);
const variants=[];
for(const[name,splicer,mustPass]of[['stock-broken-control',stock,false],['patched-import-i32-v1',selected.splicer,true]]){
 const emitted=splicer.spliceBindings(engineBytes,[],world,undefined,'profile',false);const raw=splicer.stubWasi(emitted.wasm,[],world,undefined,'profile');assert.deepEqual(WebAssembly.Module.imports(new WebAssembly.Module(raw)),[{module:'starling:raw/identity@0.1.0',name:'echo',kind:'function'}]);const reader=exportReader(raw);
 const component=Buffer.concat([skeleton.subarray(0,first.start),section(1,reader.bytes),skeleton.subarray(first.end)]);const componentPath=join(output,name+'.wasm');await writeFile(componentPath,component);const valid=spawnSync(tools,['validate',componentPath],{encoding:'utf8'});assert.equal(valid.status,0,valid.stderr);
 const wit=await componentWit(component);assert.deepEqual(wit.split('\n').filter(l=>/^\s*import /.test(l)),[]);
 const{files}=await transpile(component,{name});for(const[n,b]of Object.entries(files)){const p=join(output,n);await mkdir(dirname(p),{recursive:true});await writeFile(p,b);}const guest=await import(pathToFileURL(join(output,name+'.js')));
 const checks=[];for(const value of [-2147483648,-123456789,-1,0,1,2147483647,2147483648,2342402100,4294967295]){const op=value<=2147483647?'rawS32':'rawU32';const observed=guest[op](value);const matches=observed===value;if(mustPass)assert(matches,`${op}(${value})=${observed}`);checks.push({op,input:value,expected:value,observed,matches,carrier:'Raw JS::Value Double bits, stored with f64.store into vp[2]'});}if(!mustPass)assert(checks.some(c=>!c.matches));variants.push({name,readerFunctionIndex:reader.fid,coreSha256:sha(raw),componentPath,componentSha256:sha(component),emittedImports:[],checks});
}
const report={schemaVersion:1,atUtc:new Date().toISOString(),engine,engineSha256:sha(engineBytes),packaging:selected.provenance,wrapperSha256:sha(wat),variants,scope:'Diagnostic only. Runs the actual generated JSNative function without initializing SpiderMonkey; scratch vp=1024 is used only in this disposable core instance. The pure guest identity function is linked internally. No custom or standard external host imports. Deliberately forces negative Double carriers as well as high-u32 Doubles.'};await writeFile(join(here,selected.provenance.selection==='patched-import-i32-clock-v2'?'raw-i32-reader-v2-results.json':'raw-i32-reader-results.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(variants.map(v=>({name:v.name,passed:v.checks.filter(c=>c.matches).length,total:v.checks.length})),null,2));
